export const generateEmployeeTallyPdf = (tally: any) => {
    const doc = new jsPDF({
        orientation: 'p',
        unit: 'mm',
        format: 'a4'
    });

    // Add Watermark Logo
    const assets = getPioneerPDFAssets();
    if (assets.watermark) {
        doc.addImage(assets.watermark, 'PNG', 32, 75, 145, 145, undefined, 'FAST');
    }

    const empName = tally.employee.name;
    const empCode = tally.employee.code || 'N/A';
    const dept = tally.employee.department || tally.employee.designation || 'Staff';

    // Top Header Banner
    doc.setFillColor(37, 99, 235); // Blue
    doc.rect(0, 0, 210, 6, 'F');

    // Corporate Title
    doc.setFont("helvetica", "bold");
    doc.setFontSize(20);
    doc.setTextColor(15, 23, 42);
    doc.text("PIONEER DMS GROUP LTD", 15, 20);

    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(100, 116, 139);
    doc.text("Workforce Expense & Petty Cash Tally Statement", 15, 25);
    doc.text(`Generated on: ${new Date().toLocaleDateString()}`, 15, 29);

    // Divider Line
    doc.setDrawColor(226, 232, 240);
    doc.line(15, 33, 195, 33);

    // Employee Meta Info
    doc.setFontSize(11);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(15, 23, 42);
    doc.text("STAFF ACCOUNT DETAILS", 15, 41);

    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.text("Employee Name:", 15, 47);
    doc.setFont("helvetica", "normal");
    
    // Split long employee names to multiple lines to prevent column overlapping
    const nameLines = doc.splitTextToSize(empName, 145);
    let nameY = 47;
    nameLines.forEach((line: string, index: number) => {
        doc.text(line, 45, nameY + (index * 4.5));
    });

    const nextY = 47 + (nameLines.length * 4.5) + 1;

    // Remaining items of metadata in 2 columns
    doc.setFont("helvetica", "bold");
    doc.text("Employee Code:", 15, nextY);
    doc.setFont("helvetica", "normal");
    doc.text(empCode, 45, nextY);

    doc.setFont("helvetica", "bold");
    doc.text("Designation/Dept:", 15, nextY + 5);
    doc.setFont("helvetica", "normal");
    doc.text(dept, 45, nextY + 5);

    // Column 2
    doc.setFont("helvetica", "bold");
    doc.text("Total Advanced:", 115, nextY);
    doc.setFont("helvetica", "normal");
    doc.text(`AED ${tally.totalAdvanced.toLocaleString(undefined, {minimumFractionDigits: 2})}`, 145, nextY);

    doc.setFont("helvetica", "bold");
    doc.text("Total Expended:", 115, nextY + 5);
    doc.setFont("helvetica", "normal");
    doc.text(`AED ${tally.totalSpending.toLocaleString(undefined, {minimumFractionDigits: 2})}`, 145, nextY + 5);

    // Balance Status
    const statusLabel = tally.netBalance >= 0 ? "REMAINING BALANCE:" : "OVERSPENT DEFICIT:";
    const statusVal = `AED ${Math.abs(tally.netBalance).toLocaleString(undefined, {minimumFractionDigits: 2})} ${tally.netBalance >= 0 ? "(BALANCED)" : "(UNBALANCED)"}`;
    
    doc.setFont("helvetica", "bold");
    doc.text(statusLabel, 115, nextY + 10);
    
    if (tally.netBalance >= 0) {
        doc.setTextColor(16, 185, 129); // Green
    } else {
        doc.setTextColor(239, 68, 68); // Red
    }
    doc.text(statusVal, 153, nextY + 10);

    const dividerY = nextY + 16;

    // Divider Line
    doc.setDrawColor(226, 232, 240);
    doc.line(15, dividerY, 195, dividerY);

    // Ledger Title
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(15, 23, 42);
    doc.text("ITEMIZED TRANSACTION HISTORY LEDGER", 15, dividerY + 8);

    // Table Headers
    doc.setFillColor(248, 250, 252);
    doc.rect(15, dividerY + 13, 180, 8, 'F');
    doc.setFontSize(8.5);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(71, 85, 105);
    doc.text("DATE", 16, dividerY + 18);
    doc.text("TYPE & REFERENCE", 38, dividerY + 18);
    doc.text("DESCRIPTION / SHOP / SUPPLIER", 82, dividerY + 18);
    doc.text("CREDIT (IN)", 170, dividerY + 18, { align: "right" });
    doc.text("DEBIT (OUT)", 194, dividerY + 18, { align: "right" });

    // Let's merge both Petty Cash items and Everyday Expenses sorted chronologically
    const ledgerEntries: any[] = [];
    tally.pettyCashItems.forEach((p: any) => {
        ledgerEntries.push({
            date: p.date,
            ref: p.type === 'Income' ? 'Petty Cash Advance' : `Petty Spent (${p.category})`,
            desc: p.description,
            credit: p.type === 'Income' ? Number(p.amount) : 0,
            debit: p.type === 'Expense' ? Number(p.amount) : 0
        });
    });

    tally.everydayItems.forEach((ee: any) => {
        ledgerEntries.push({
            date: ee.date,
            ref: `Everyday Expense #${ee.invoiceNo || 'N/A'}`,
            desc: `${ee.description || ''} at ${ee.shopName || ee.supplierName || 'General'}`,
            credit: 0,
            debit: Number(ee.totalAmount) || Number(ee.billAmount) || 0
        });
    });

    // Sort entries by date ascending safely
    ledgerEntries.sort((a, b) => (a.date || '').localeCompare(b.date || ''));

    let y = dividerY + 25;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.setTextColor(51, 65, 85);

    ledgerEntries.forEach((entry, idx) => {
        // Sanitize ref and desc
        const cleanRef = sanitizePdfText(entry.ref);
        const cleanDesc = sanitizePdfText(entry.desc);

        // Split ref and desc to fit their respective column widths
        const refLines = doc.splitTextToSize(cleanRef, 40);
        const descLines = doc.splitTextToSize(cleanDesc, 80);

        // Find the height needed for this row
        const lineCount = Math.max(refLines.length, descLines.length, 1);
        const rowHeight = lineCount * 5.2 + 2.8; // some padding

        // Check if we need a new page
        if (y + rowHeight > 280) {
            doc.addPage();
            // Reprint Header
            doc.setFillColor(37, 99, 235);
            doc.rect(0, 0, 210, 6, 'F');
            
            // Reprint Table Headers on the new page!
            doc.setFillColor(248, 250, 252);
            doc.rect(15, 12, 180, 8, 'F');
            doc.setFontSize(8.5);
            doc.setFont("helvetica", "bold");
            doc.setTextColor(71, 85, 105);
            doc.text("DATE", 16, 17);
            doc.text("TYPE & REFERENCE", 38, 17);
            doc.text("DESCRIPTION / SHOP / SUPPLIER", 82, 17);
            doc.text("CREDIT (IN)", 170, 17, { align: "right" });
            doc.text("DEBIT (OUT)", 194, 17, { align: "right" });
            
            y = 25;
            doc.setFont("helvetica", "normal");
            doc.setFontSize(8);
            doc.setTextColor(51, 65, 85);
        }

        // Alternating row background
        if (idx % 2 === 1) {
            doc.setFillColor(248, 250, 252);
            doc.rect(15, y - 4, 180, rowHeight, 'F');
        }

        // Print Date
        doc.text(entry.date || '-', 16, y);

        // Print Type & Reference lines
        refLines.forEach((line: string, i: number) => {
            doc.text(line, 38, y + (i * 5.2));
        });

        // Print Description lines
        descLines.forEach((line: string, i: number) => {
            doc.text(line, 82, y + (i * 5.2));
        });

        // Print Credit & Debit right aligned
        const creditText = entry.credit > 0 ? `AED ${entry.credit.toLocaleString(undefined, {minimumFractionDigits: 2})}` : "-";
        const debitText = entry.debit > 0 ? `AED ${entry.debit.toLocaleString(undefined, {minimumFractionDigits: 2})}` : "-";
        doc.text(creditText, 170, y, { align: "right" });
        doc.text(debitText, 194, y, { align: "right" });

        y += rowHeight;
    });

    // Draw End Line
    doc.setDrawColor(226, 232, 240);
    doc.line(15, y, 195, y);

    // Grand Totals Row
    y += 6;
    doc.setFont("helvetica", "bold");
    doc.text("GRAND RECONCILIATION TOTALS:", 16, y);
    doc.text(`AED ${tally.totalAdvanced.toLocaleString(undefined, {minimumFractionDigits: 2})}`, 170, y, { align: "right" });
    doc.text(`AED ${tally.totalSpending.toLocaleString(undefined, {minimumFractionDigits: 2})}`, 194, y, { align: "right" });

    doc.save(`Reconciliation_Tally_${empName.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.pdf`);
};

